mockup.css:
.mock-section-step-rail { background: #f2f0e9; color: #16150f; font-family: var(--f-sans);
  display: flex; flex-direction: column; justify-content: center; gap: 3.6cqw; padding: 0 6cqw; }
.mock-section-step-rail h4 { margin: 0; font-family: var(--f-serif); font-size: 3.4cqw; line-height: 1.06; }
.mock-section-step-rail .rail { display: grid; grid-template-columns: repeat(4, 1fr); }
.mock-section-step-rail .step { padding-right: 3.4cqw; display: flex; flex-direction: column; gap: 1.3cqw;
  position: relative; }
.mock-section-step-rail .step:not(:last-child)::after { content: ""; position: absolute;
  inset-inline: 3.4cqw 0; top: 1.7cqw; block-size: 1px; background: rgba(22,21,15,.28); }
.mock-section-step-rail .step b { position: relative; z-index: 1; inline-size: 3.4cqw; block-size: 3.4cqw;
  border-radius: 50%; background: #16150f; color: #f2f0e9; display: grid; place-items: center;
  font-family: var(--f-mono); font-size: 1.25cqw; }
.mock-section-step-rail .step strong { font-size: 1.85cqw; font-weight: 600; }
.mock-section-step-rail .step p { margin: 0; font-size: 1.35cqw; line-height: 1.5; opacity: .66; }
